'use strict';
(()=>{
const path=location.pathname.replace(/\/+$/,'')||'/';
const finalImages={'Black London':'/assets/spray-products-final/black-london-new.png','Sweet Rose':'/assets/spray-products-final/sweet-rose-new.png','Velvet Night':'/assets/spray-products-final/velvet-night-new.png','Machmoun':'/assets/spray-products-final/machmoun-new.png','Cotton Candy':'/assets/spray-products-final/cotton-candy-new.png','بلاك لندن':'/assets/spray-products-final/black-london-new.png','سويت روز':'/assets/spray-products-final/sweet-rose-new.png','فيلفت نايت':'/assets/spray-products-final/velvet-night-new.png','المشموم':'/assets/spray-products-final/machmoun-new.png','كوتن كاندي':'/assets/spray-products-final/cotton-candy-new.png'};
const homeStyle=document.createElement('style');homeStyle.textContent=`#bakhoor-products{display:grid!important;grid-template-columns:repeat(5,minmax(0,1fr))!important;gap:18px!important;max-width:none!important;overflow:visible!important;scroll-snap-type:none!important}#bakhoor-products .product-card{min-width:0!important;width:auto!important;flex:none!important}@media(max-width:900px){#bakhoor-products{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:14px!important}}@media(max-width:600px){#bakhoor-products{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:10px!important}#bakhoor-products .product-card h3{font-size:18px!important}#bakhoor-products .product-card .type,#bakhoor-products .product-card .price{font-size:11px!important}#bakhoor-products .card-add{width:100%!important;min-width:0!important;padding:10px 6px!important}}`;document.head.appendChild(homeStyle);
function fixHome(){const grid=document.querySelector('#home-products');if(grid)grid.querySelectorAll('.product-card').forEach(card=>{const title=(card.querySelector('h3')?.textContent||'').trim();const img=card.querySelector('img');const src=finalImages[title];if(src&&img&&img.getAttribute('src')!==src){img.src=src;img.removeAttribute('srcset');}});const privateGrid=document.querySelector('#bakhoor-products');if(privateGrid&&typeof products!=='undefined'&&typeof card==='function'){const ids=['sultana-oud','royal-bukhoor','amber-night','oud-collection-set','bakhoor-burner'];const html=ids.map(id=>products.find(p=>p.id===id)).filter(Boolean).map(card).join('');if(html&&privateGrid.querySelectorAll('.product-card').length!==5)privateGrid.innerHTML=html;}}

if(path==='/oud-bakhoor'){
const css=document.createElement('style');css.textContent=`header>.header-actions .desktop-language-switch,header>.header-actions>a[lang="ar"],header>.header-actions>a[hreflang="ar"]{display:none!important}.oud-approved-hero{width:100%;aspect-ratio:3/1;overflow:hidden;background:#1c1712}.oud-approved-hero img{width:100%;height:100%;object-fit:cover;display:block}.oud-private{padding-top:28px;padding-bottom:40px}.oud-private-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.oud-private-head h2,.oud-prestige h2{margin:0;font-weight:400}.oud-private-nav{display:none!important}.oud-private-track{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px}.oud-card{text-align:center;min-width:0}.oud-card .pic{aspect-ratio:1/1;overflow:hidden;background:#f4eee6}.oud-card .pic img{width:100%;height:100%;object-fit:cover;display:block}.oud-card h3{font-family:var(--serif,Georgia,serif);font-size:21px;font-weight:400;margin:12px 0 3px}.oud-card .kind{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:#8a8178;margin:0 0 7px}.oud-card .price{font-size:12px;margin:0 0 13px}.oud-card button{min-width:0;width:100%;padding:10px 8px;border:1px solid #d4b993;background:transparent}.oud-prestige{padding-top:10px;padding-bottom:55px}.oud-prestige .eyebrow{margin-bottom:6px}.oud-prestige-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin-top:18px}.oud-prestige-grid .product-card .product-kind,.oud-prestige-grid .product-card .type{display:none!important}@media(max-width:900px){.oud-private-track,.oud-prestige-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}}@media(max-width:600px){.oud-approved-hero{aspect-ratio:3/1}.oud-private{padding-top:22px}.oud-private-head h2,.oud-prestige h2{font-size:30px}.oud-private-track,.oud-prestige-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:10px!important;overflow:visible!important;scroll-snap-type:none!important}.oud-card,.oud-prestige-grid .product-card{min-width:0!important;width:auto!important;flex:none!important}.oud-card h3{font-size:18px}.oud-card .kind,.oud-card .price{font-size:10px}.oud-card button{font-size:11px;padding:9px 4px}.oud-prestige-grid .card-add{width:100%!important;min-width:0!important}}`;document.head.appendChild(css);
const privateItems=[['sultana-oud','Sultana Oud','/assets/new-products/sultana-oud-hd.webp','QAR 350'],['royal-bukhoor','Royal Bukhoor','/assets/new-products/royal-bukhoor-hd.webp','QAR 350'],['amber-night','Amber Night','/assets/new-products/amber-night-hd.webp','QAR 350'],['oud-collection-set','Oud & Bakhoor Gift Set','/assets/new-products/oud-collection-set.webp','QAR 1,100'],['bakhoor-burner','Bakhoor Burner','/assets/new-products/bakhoor-burner-hd.webp','']];
function oudPrivateCard(x){return `<article class="oud-card"><a href="/products/${x[0]}/"><div class="pic"><img src="${x[2]}" alt="${x[1]}"></div></a><h3>${x[1]}</h3><p class="kind">Private Collection</p>${x[3]?`<p class="price">${x[3]}</p>`:''}<button type="button" data-add-product="${x[0]}">ADD TO BAG</button></article>`}
function restoreOud(){const main=document.querySelector('#main-content');if(!main||main.dataset.approvedOud==='1')return;main.dataset.approvedOud='1';main.innerHTML=`<section class="oud-approved-hero" aria-label="Oud & Bakhoor"><img src="/assets/WhatsApp%20Image%202026-09-21%20at%2015.25.27.jpeg" alt="The Essence of Heritage"></section><section class="section-shell oud-private"><div class="oud-private-head"><h2>Private Collection</h2></div><div class="oud-private-track">${privateItems.map(oudPrivateCard).join('')}</div></section><section class="section-shell oud-prestige" id="collection"><p class="eyebrow">PRESTIGE COLLECTION</p><h2>The Prestige Collection</h2><div class="oud-prestige-grid" id="oud-prestige-grid"></div></section>`;fillPrestige();}
function fillPrestige(){const grid=document.querySelector('#oud-prestige-grid');if(!grid||typeof products==='undefined'||typeof card!=='function')return false;const ids=['oud-amber','oud-oudy','oud-private','maamoul-doha','bakhour-al-sheikha','bakhour-hala-ghala','luban-with-oud'];const found=ids.map(id=>products.find(p=>p.id===id)).filter(Boolean);if(!found.length)return false;grid.innerHTML=found.map(card).join('');return true;}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',restoreOud,{once:true});else restoreOud();let tries=0;const timer=setInterval(()=>{restoreOud();if(fillPrestige()||++tries>30)clearInterval(timer)},100);return;
}

if(path!=='/room-sprays'){fixHome();const observer=new MutationObserver(fixHome);observer.observe(document.documentElement,{childList:true,subtree:true});return;}
const sprayIds=['black-london','sweet-rose','velvet-night','machmoun','cotton-candy','royal-fruity','wood-bouquet','my-mood','blanc-imperial'];
const sprayNames={'black-london':'Black London','sweet-rose':'Sweet Rose','velvet-night':'Velvet Night','machmoun':'Machmoun','cotton-candy':'Cotton Candy','royal-fruity':'Royal Fruity','wood-bouquet':'Wood Bouquet','my-mood':'My Mood','blanc-imperial':'Blanc Imperial'};
const css=document.createElement('style');css.textContent=`.spray-latest-hero{width:100%;aspect-ratio:3/1;overflow:hidden;background:#1c1712}.spray-latest-hero img{width:100%;height:100%;object-fit:cover;display:block}.spray-use-cards{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:16px!important}.spray-use-cards .category-card{position:relative;display:block;overflow:hidden;background:#eee;aspect-ratio:4/3!important;height:auto!important}.spray-use-cards .category-card:after{display:none!important}.spray-use-cards img{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;max-width:none!important;object-fit:cover!important;object-position:center center!important;display:block!important;margin:0!important;transform:none!important}.spray-use-cards .category-card:hover img{transform:none!important}.spray-products-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}.spray-product-card{border:1px solid #d8c4a6;padding:8px;text-align:center;background:#fff;min-width:0}.spray-product-card a{color:inherit;text-decoration:none}.spray-product-image{aspect-ratio:1/1;overflow:hidden;background:#f3eee5}.spray-product-image img{width:100%;height:100%;display:block;object-fit:cover}.spray-product-card h3{font-family:serif;font-size:26px;font-weight:400;margin:16px 5px 8px}.spray-product-card p{font-size:12px;letter-spacing:.04em;color:#756f68;margin:0 0 12px}.spray-product-card .price{font-size:15px;color:#1d1915;margin-bottom:16px}.spray-product-card .add-btn{display:block;margin:0 auto 10px;width:65%;padding:12px;border:1px solid #cdb18d;background:transparent;font-size:14px}.spray-latest-bottom{width:100%;overflow:hidden}.spray-latest-bottom img{display:block;width:100%;height:auto}@media(max-width:900px){.spray-products-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.spray-latest-hero{aspect-ratio:3/1}.spray-use-cards{display:grid!important;grid-template-columns:1fr!important;overflow:visible!important;gap:10px!important;scroll-snap-type:none!important}.spray-use-cards .category-card{width:100%!important;aspect-ratio:4/3!important}.spray-products-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.spray-product-card h3{font-size:19px;margin-top:10px}.spray-product-card p{font-size:10px}.spray-product-card .price{font-size:13px}.spray-product-card .add-btn{width:100%;font-size:11px;padding:10px 4px}}`;document.head.appendChild(css);
function productCard(id){const name=sprayNames[id];const img=`/assets/spray-products-final/${id}-new.png`;return `<article class="spray-product-card"><a href="/products/${id}/"><div class="spray-product-image"><img src="${img}" alt="${name} by Sultana" loading="lazy" onerror="this.onerror=null;this.src='/assets/products-square/${id}.webp'"></div><h3>${name}</h3></a><p>LUXURY HOME SPRAY · 300 ML</p><div class="price">QAR 120</div><button class="add-btn" type="button" data-product-id="${id}">ADD TO BAG</button></article>`}
function restore(){const main=document.querySelector('#main-content');if(!main||main.dataset.latestSpray==='2')return;main.dataset.latestSpray='2';main.innerHTML=`<section class="spray-latest-hero" aria-label="Luxury Spray Collection"><img src="/assets/ChatGPT%20Image%20Sep%2021%2C%202026%2C%2007_02_23%20PM.png" alt="The Ambiance Collection"></section><section class="section-shell department-categories"><div class="section-heading"><div><h2>One Mist. Many Moments.</h2></div><a class="text-link" href="#collection">View all</a></div><div class="category-section spray-use-cards"><a class="category-card" href="#collection"><img src="/assets/use-room-mist.png" alt="Room Mist"></a><a class="category-card" href="#collection"><img src="/assets/use-car-mist.png" alt="Car Mist"></a><a class="category-card" href="#collection"><img src="/assets/use-clothing-mist.png" alt="Clothing Mist"></a></div></section><section class="shop-section section-shell" id="collection"><div class="section-heading"><div><h2>The Ambiance Collection</h2></div></div><div class="spray-products-grid">${sprayIds.map(productCard).join('')}</div></section><section class="perfume-gift-banner spray-latest-bottom" id="spray-gift-banner"><a href="/shop/?collection=gift#collection"><img src="/assets/campaigns/spray-bottom-banner.webp" alt="Luxury Spray Gift Set" loading="lazy"></a></section>`;}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',restore,{once:true});else restore();setTimeout(restore,100);
})();
